import os
import json
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
OUT = Path(os.environ["OUTPUT_DIR"])

dates = [f"201902{d:02d}" for d in range(2, 9)]
segments = {("南通站", "如皋站"), ("如皋站", "海安站")}
lines = {"中俄东线", "冀宁线"}

per_day = {}
totals = {}
rows_found = []

for date in dates:
    csv_path = DIR / f"{date}_pipeline.csv"
    if not csv_path.exists():
        per_day[date] = None
        continue
    day = {}
    with open(csv_path, encoding="utf-8") as f:
        header = f.readline()
        for line in f:
            parts = line.rstrip("\n").split(",")
            if len(parts) < 5:
                continue
            start, end, typ, line_name, flow = parts[0], parts[1], parts[2], parts[3], parts[4]
            try:
                fv = float(flow)
            except ValueError:
                continue
            if (start, end) in segments and line_name in lines:
                key = (start, end, line_name)
                day[key] = day.get(key, 0.0) + abs(fv)
                totals[key] = totals.get(key, 0.0) + abs(fv)
                rows_found.append((date, start, end, typ, line_name, fv))
    per_day[date] = day

print("=== rows found ===")
for r in rows_found:
    print(r)
print("=== per-day absolute flow sums ===")
for date, day in per_day.items():
    print(date, day)
print("=== cumulative totals (20190202-20190208) ===")
for key, val in sorted(totals.items()):
    print(key, round(val, 3))

payload = {
    "window": ["20190202", "20190208"],
    "segments": [list(s) for s in segments],
    "per_day": {d: {f"{k[0]}|{k[1]}|{k[2]}": v for k, v in day.items()} if day else None for d, day in per_day.items()},
    "cumulative": {f"{k[0]}|{k[1]}|{k[2]}": val for k, val in sorted(totals.items())},
}
(out := OUT / "segment_flow_summary.json").write_text(
    json.dumps(payload, ensure_ascii=False, indent=2, default=str), encoding="utf-8"
)
print("written:", out)

